entries[13506] = { ["name"] = "Fläschchen der Versteinerung", ["text"] = "Benötigt Stufe 50\nBenutzen: Ihr werdet zu Stein und seid 1 Min. lang gegen alle körperlichen Angriffe und Zauber geschützt, allerdings könnt Ihr während dieser Zeit weder angreifen noch Euch bewegen und auch keine Zauber wirken. Es kann immer nur der Effekt von jeweils einem Fläschchen aktiv sein. (3 Sek. Abklingzeit)" }
